using System.Collections.Concurrent;
using System.IO;
using System.Windows;
using NAudio.CoreAudioApi;
using NAudio.Wave;

namespace SmoothCoder.App.Services;

/// <summary>Which spoken announcement to play. Each value maps to one WAV under
/// <c>Assets/Voice</c>, pre-generated by <c>scripts/generate-voice.ps1</c> and shipped with the app -
/// nothing is synthesized at runtime, so an unattended failover still announces itself with no network
/// and no API key anywhere in the build.</summary>
public enum VoiceCue
{
    /// <summary>A usage limit was detected and a failover has been armed.</summary>
    LimitDetected,

    /// <summary>The task is moving to Codex CLI.</summary>
    HandoffToCodex,

    /// <summary>The task is moving to Claude Code.</summary>
    HandoffToClaude,

    /// <summary>The task is being picked back up on the same agent after its reset.</summary>
    AutoResume,

    /// <summary>Both accounts are exhausted; the task is parked until the first reset.</summary>
    WaitingForReset,

    /// <summary>A session is blocked on the user - a permission prompt, or an AskUserQuestion/
    /// ExitPlanMode confirmation. Claude Code only - see <see cref="StatusMarkerStore"/>; Codex has no
    /// equivalent signal to key off.</summary>
    AwaitingApproval,

    /// <summary>A session finished its turn and is waiting for the next instruction. The everyday cue,
    /// and the only one that fires while someone is sitting at the keyboard - it replaces what the
    /// ~/.claude/hooks/notify-sound.py hook used to play for itself, so that both CLIs announce this
    /// through one volume control instead of Claude Code having a second, louder voice of its own.
    /// Claude Code reports it through the Stop hook's marker; Codex through its transcript's
    /// <c>task_complete</c> record.</summary>
    TurnComplete,

    /// <summary>An automatic resume threw. This is the one cue that means the unattended run has
    /// actually stopped.</summary>
    ResumeFailed,
}

/// <summary>Plays the spoken notification cues. Shared by every project regardless of which CLI it
/// runs, so the limit/handoff/resume/failure announcements are common to Claude Code and Codex alike.
///
/// <para>Volume is applied by scaling the samples (see <see cref="WavAudio.Scale"/>) because the
/// playback device has no per-clip volume of its own. That makes the slider an app-level control,
/// independent of the Windows mixer.</para>
///
/// <para>Nothing here is allowed to throw at its caller. Every entry point is wrapped, and a missing
/// or unreadable asset degrades to a plain tone rather than silence, since the cue's whole job is to
/// be the only indication a human gets that an unattended run changed state.</para></summary>
public sealed class VoiceNotificationService
{
    /// <summary>How long the same cue is suppressed after playing. The dashboard re-evaluates activity
    /// every two seconds, so a cue driven by a state that stays true would otherwise repeat forever;
    /// callers fire on transitions, and this is the backstop if one ever doesn't.</summary>
    private static readonly TimeSpan RepeatSuppression = TimeSpan.FromSeconds(5);

    private static readonly TimeSpan FallbackToneLength = TimeSpan.FromMilliseconds(220);
    private const double FallbackToneHz = 880;

    private readonly ConcurrentDictionary<VoiceCue, byte[]> _assetCache = new();
    private readonly Dictionary<VoiceCue, DateTimeOffset> _lastPlayed = [];
    private readonly SemaphoreSlim _playbackGate = new(1, 1);
    private readonly Lock _debounceLock = new();
    private readonly Func<DateTimeOffset> _clock;

    public VoiceNotificationService(Func<DateTimeOffset>? clock = null) => _clock = clock ?? (() => DateTimeOffset.Now);

    /// <summary>Master on/off, mirrored from <see cref="Models.AppSettings.VoiceNotificationEnabled"/>.</summary>
    public bool Enabled { get; set; } = true;

    /// <summary>Whether <see cref="VoiceCue.TurnComplete"/> is wanted, mirrored from
    /// <see cref="Models.AppSettings.VoiceTurnCompleteEnabled"/>. Separate from <see cref="Enabled"/>
    /// because it is the one cue that fires during ordinary attended work, many times an hour, whereas
    /// the rest only mark an unattended run changing state - someone who wants to be told about a
    /// failover at 3am doesn't necessarily want to be told about every turn at noon. Enforced here
    /// rather than at each call site so there is one place that decides.</summary>
    public bool TurnCompleteEnabled { get; set; } = true;

    /// <summary>0.0-1.0 slider position, mirrored from
    /// <see cref="Models.AppSettings.VoiceNotificationVolume"/>. Converted to an amplitude factor via
    /// <see cref="WavAudio.PerceptualAmplitude"/> at playback.</summary>
    public double Volume { get; set; } = 0.7;

    /// <summary>Why playback last failed, or null while healthy. Written from the playback thread and
    /// read for diagnostics only - it is deliberately not surfaced in the UI, because the settings
    /// tab's test button is the direct answer to "is sound working" and a bound error string would
    /// need this to be observable for no other reason.</summary>
    public string? LastError { get; private set; }

    /// <summary>Queues <paramref name="cue"/> and returns immediately. Cues play one after another
    /// rather than cutting each other off, so a limit-detected announcement isn't truncated by the
    /// handoff announcement that follows it seconds later.</summary>
    public void Play(VoiceCue cue)
    {
        if (!Enabled || (cue == VoiceCue.TurnComplete && !TurnCompleteEnabled) || !TryClaimSlot(cue))
        {
            return;
        }

        PlayNow(cue);
    }

    /// <summary>Plays regardless of <see cref="Enabled"/> and the repeat suppression - for the
    /// settings tab's test button, where the point is to hear the current volume immediately.</summary>
    public void PlayTest(VoiceCue cue = VoiceCue.AutoResume) => PlayNow(cue);

    private void PlayNow(VoiceCue cue)
    {
        var amplitude = WavAudio.PerceptualAmplitude(Volume);

        // Application.GetResourceStream resolves WPF pack resources through the application's
        // dispatcher. The settings button is invoked on that dispatcher, whereas the old code tried
        // to resolve it inside Task.Run's MTA worker. On some installations that lookup fails, so
        // the test appeared to do nothing. Read and scale the small WAV before queuing playback;
        // the worker now deals only with an ordinary byte array.
        byte[] wav;
        try
        {
            wav = WavAudio.Scale(LoadAsset(cue), amplitude);
        }
        catch (Exception ex)
        {
            LastError = ex.Message;
            return;
        }

        // System.Media.SoundPlayer can silently produce no output with some Windows endpoint
        // drivers. WasapiOut addresses the current default render endpoint directly instead.
        // The gate keeps cues serialized, and the thread is background-only so it cannot delay exit.
        var playbackThread = new Thread(() =>
        {
            _playbackGate.Wait();
            try
            {
                using var stream = new MemoryStream(wav, writable: false);
                using var reader = new WaveFileReader(stream);
                using var player = new WasapiOut(AudioClientShareMode.Shared, useEventSync: false, latency: 100);
                player.Init(reader);
                player.Play();
                while (player.PlaybackState == PlaybackState.Playing)
                {
                    Thread.Sleep(20);
                }
                LastError = null;
            }
            catch (Exception ex)
            {
                // A notification that cannot be heard must never stop the failover it was announcing.
                LastError = ex.Message;
            }
            finally
            {
                _playbackGate.Release();
            }
        })
        {
            IsBackground = true,
            Name = "SmoothCoder voice playback",
        };
        playbackThread.SetApartmentState(ApartmentState.STA);
        playbackThread.Start();
    }

    private bool TryClaimSlot(VoiceCue cue)
    {
        var now = _clock();
        lock (_debounceLock)
        {
            if (_lastPlayed.TryGetValue(cue, out var last) && now - last < RepeatSuppression)
            {
                return false;
            }

            _lastPlayed[cue] = now;
            return true;
        }
    }

    /// <summary>Reads the cue's WAV out of the app's resources, caching it - the assets are a few
    /// hundred KB each and a long unattended run replays the same handful many times. Falls back to a
    /// generated tone if the resource is missing (an incomplete build) or unreadable.</summary>
    private byte[] LoadAsset(VoiceCue cue) => _assetCache.GetOrAdd(cue, static key =>
    {
        try
        {
            var resource = Application.GetResourceStream(AssetUri(key));
            if (resource is null)
            {
                return WavAudio.BuildTone(FallbackToneHz, FallbackToneLength, 1.0);
            }

            using var stream = resource.Stream;
            using var buffer = new MemoryStream();
            stream.CopyTo(buffer);
            return WavAudio.NormalizeLengths(buffer.ToArray());
        }
        catch (Exception e) when (e is IOException or UriFormatException or InvalidOperationException or NotSupportedException)
        {
            return WavAudio.BuildTone(FallbackToneHz, FallbackToneLength, 1.0);
        }
    });

    /// <summary>Where <paramref name="cue"/>'s WAV lives. Assembly-qualified (<c>;component</c>)
    /// rather than the shorter relative form, which resolves against whichever assembly happens to
    /// own <see cref="Application.ResourceAssembly"/> - fine inside the running app, but it would make
    /// this unresolvable anywhere else, including from the tests that check the assets are wired up.</summary>
    public static Uri AssetUri(VoiceCue cue)
    {
        // WPF registers the "pack" scheme lazily. Inside the running app an Application instance has
        // always done that by the time a cue plays, but without it Uri parses "pack://application:,,,"
        // as a generic authority and fails on the port - so register it here rather than depend on
        // something else having touched WPF first.
        if (!UriParser.IsKnownScheme("pack"))
        {
            _ = System.IO.Packaging.PackUriHelper.UriSchemePack;
        }

        return new Uri(
            $"pack://application:,,,/Smooth-Coder.App;component/Assets/Voice/{AssetFileName(cue)}",
            UriKind.Absolute);
    }

    /// <summary>Must stay in step with the phrase table in <c>scripts/generate-voice.ps1</c>.</summary>
    private static string AssetFileName(VoiceCue cue) => cue switch
    {
        VoiceCue.LimitDetected => "limit-detected.wav",
        VoiceCue.HandoffToCodex => "handoff-to-codex.wav",
        VoiceCue.HandoffToClaude => "handoff-to-claude.wav",
        VoiceCue.AutoResume => "auto-resume.wav",
        VoiceCue.WaitingForReset => "waiting-for-reset.wav",
        VoiceCue.AwaitingApproval => "awaiting-approval.wav",
        VoiceCue.TurnComplete => "turn-complete.wav",
        VoiceCue.ResumeFailed => "resume-failed.wav",
        _ => "auto-resume.wav",
    };

    /// <summary>The handoff announcement for whichever CLI is being started, or null for an agent with
    /// no recorded announcement (only Claude Code and Codex take part in handoffs).</summary>
    public static VoiceCue? HandoffCueFor(Models.AgentKind target) => target switch
    {
        Models.AgentKind.ClaudeCode => VoiceCue.HandoffToClaude,
        Models.AgentKind.CodexCli => VoiceCue.HandoffToCodex,
        _ => null,
    };
}
